from hypothesis import strategies as st


@st.composite
def gen(draw):
    q = draw(st.integers(1, 12))
    bag = {}
    ops = []
    for _ in range(q):
        kinds = [1, 3]
        if any(c > 0 for c in bag.values()):
            kinds.append(2)
        kind = draw(st.sampled_from(kinds))
        if kind == 1:
            x = draw(st.integers(1, 4))
            bag[x] = bag.get(x, 0) + 1
            ops.append(f"1 {x}")
        elif kind == 2:
            present = [x for x, c in bag.items() if c > 0]
            x = draw(st.sampled_from(present))
            bag[x] -= 1
            ops.append(f"2 {x}")
        else:
            ops.append("3")
    if not any(op == "3" for op in ops):
        ops.append("3")
        q += 1
    return f"{q}\n" + "\n".join(ops) + "\n"


